formData.jsFunction:
def addError(response, key, msg) {
    if (response[key] == null) response[key] = msg
    else if (response[key] instanceof List) response[key] << msg
    else response[key] = [response[key], msg]
}

def validate(request, response = [:]) {
    def schOp = request.ScheduleOptions ?: [:]
    def frequency = schOp.Frequency
    def repeatsEvery = (schOp.RepeatsEvery ?: 0) as int
    def daysOfWeek = schOp.DaysofWeek

    if (frequency != "Monthly" && frequency != "Daily" && frequency != "Yearly" && repeatsEvery > 2 && daysOfWeek != null && daysOfWeek.size() > 0) {
        addError(response, "RepeatsEvery", "The combination of repeat and Repeat On is not possible.")
    }

    return response
}
